// One element through its view: prepare, check (when check), hash. Nothing is written.
::grvt::Result<void> hash_element_order_bulk_orders(const models::ApiCreateOrderRequestInput& d, const ::grvt::SignContext& ctx, sign::Pending& out) {
  auto prepared = sign::prepare(sig_ptr_order_bulk_orders(d), ctx);
  if (!prepared) return ::std::move(prepared).error();
  const sign::Prepared& p = *prepared;
  const sign::Meta meta(ctx);
  const sign::TypeDef*& st = out.st;
  ::grvt::Bytes32& hash = out.hash;
  ::grvt::Result<void> hashed;
  const auto* v1 = sign::ptr(d.order);
  const auto* v2 = v1 ? sign::ptr(v1->builder) : nullptr;
  if (auto valid = sign::address(v2, "order.builder"); !valid) return ::std::move(valid).error();
  if (sign::address_set(v2)) {
    st = &EIP712_ORDER_WITH_BUILDER_FEE;
    hashed = hash_order_with_builder_fee(d, meta, p, hash);
  } else {
    st = &EIP712_ORDER;
    hashed = hash_order(d, meta, p, hash);
  }
  if (!hashed) return ::std::move(hashed).error();
  out.p = p;
  return {};
}

::grvt::Result<void> hash_elements_order_bulk_orders(::std::vector<models::OrderInput>& elements, const ::grvt::SignContext& ctx, ::std::vector<sign::Pending>& out) {
  out.resize(elements.size());
  models::ApiCreateOrderRequestInput view(::grvt::detail::Uninitialized{});
  for (::std::size_t i = 0; i < elements.size(); ++i) {
    view.order = ::std::move(elements[i]);
    auto r = hash_element_order_bulk_orders(view, ctx, out[i]);
    elements[i] = ::std::move(view.order);
    if (!r) return r;
  }
  return {};
}

::grvt::Result<void> sign_order_bulk_orders(models::ApiBulkOrdersRequestInput& req, const ::grvt::SignContext& ctx) {
  if (!req.orders) return {};
  auto& elements = *req.orders;
  ::std::vector<sign::Pending> pending;
  if (auto r = hash_elements_order_bulk_orders(elements, ctx, pending); !r) return r;
  for (::std::size_t i = 0; i < pending.size(); ++i) {
    auto& e = pending[i];
    const sign::TypedSource<models::OrderInput> typed{&elements[i], &ctx, e.p};
    auto s = sign::sign_hashed(ctx, e.p.chain_id, *e.st, e.hash, &typed, &typed_order_bulk_orders);
    if (!s) return ::std::move(s).error();
    e.sig = ::std::move(*s);
  }
  for (::std::size_t i = 0; i < elements.size(); ++i) sign::commit(sig_element_order_bulk_orders(elements[i]), pending[i].p, pending[i].sig);
  return {};
}

::grvt::Result<void> digests_order_bulk_orders(models::ApiBulkOrdersRequestInput& req, const ::grvt::SignContext& ctx, ::std::vector<::grvt::SigningRequest>& out) {
  out.clear();
  if (!req.orders) return {};
  auto& elements = *req.orders;
  ::std::vector<sign::Pending> pending;
  if (auto r = hash_elements_order_bulk_orders(elements, ctx, pending); !r) return r;
  out.reserve(pending.size());
  for (const auto& e : pending) out.push_back(sign::signing_request(ctx, e.p.chain_id, *e.st, e.hash));
  for (::std::size_t i = 0; i < elements.size(); ++i) sign::commit_prepared(sig_element_order_bulk_orders(elements[i]), pending[i].p);
  return {};
}

::grvt::Result<void> attach_order_bulk_orders(models::ApiBulkOrdersRequestInput& req, const ::grvt::SignContext& ctx, ::std::span<const ::grvt::RawSignature> signatures) {
  const ::std::size_t n = req.orders ? req.orders->size() : 0;
  if (signatures.size() != n) {
    return ::grvt::Error::config(::std::to_string(signatures.size()) + " signatures for " + ::std::to_string(n) + " elements of order.bulk_orders");
  }
  if (n == 0) return {};
  if (!req.orders) return {};
  auto& elements = *req.orders;
  for (const auto& element : elements) {
    if (!sign::fully_prepared(sig_element_ptr_order_bulk_orders(element))) {
      return ::grvt::Error::config("order.bulk_orders: an element has no prepared signature; call digests_order_bulk_orders first");
    }
  }
  ::std::vector<sign::Pending> pending;
  if (auto r = hash_elements_order_bulk_orders(elements, ctx, pending); !r) return r;
  for (::std::size_t i = 0; i < n; ++i) {
    const auto signed_request = sign::signing_request(ctx, pending[i].p.chain_id, *pending[i].st, pending[i].hash);
    if (auto ok = sign::check_recovered(ctx, signed_request, signatures[i]); !ok) return ok;
  }
  for (::std::size_t i = 0; i < n; ++i) sign::commit(sig_element_order_bulk_orders(elements[i]), pending[i].p, signatures[i]);
  return {};
}

