::grvt::Result<::std::string> typed_transfer_transfer(const void* source) {
  const auto& t = *static_cast<const sign::TypedSource<models::ApiTransferRequestInput>*>(source);
  const auto& d = *t.req;
  const sign::Meta meta(*t.ctx);
  const sign::Prepared& p = t.p;
  const sign::TypeDef* st = nullptr;
  ::std::string json;
  ::grvt::Result<void> hashed;
  const auto* v1 = sign::ptr(d.currency);
  const auto* v2 = sign::ptr(d.from_wallet_type);
  const auto* v3 = sign::ptr(d.to_wallet_type);
  auto currency = meta.currency(v1);
  if (!currency) return ::std::move(currency).error();
  const auto currency_id = (*currency)->id;
  if ((v2 == nullptr) != (v3 == nullptr)) {
    return ::grvt::Error::signing("set both from_wallet_type and to_wallet_type, or neither");
  }
  if (v2 == nullptr) {
    if (currency_id > 255) {
      return ::grvt::Error::signing("currency id " + ::std::to_string(currency_id) + " needs from_wallet_type and to_wallet_type");
    }
    st = &EIP712_TRANSFER;
    hashed = json_transfer(d, meta, p, json);
  } else if (currency_id <= 255) {
    st = &EIP712_TRANSFER_V2;
    hashed = json_transfer_v2(d, meta, p, json);
  } else {
    st = &EIP712_TRANSFER_V3;
    hashed = json_transfer_v3(d, meta, p, json);
  }
  if (!hashed) return ::std::move(hashed).error();
  return sign::typed_document(*st, p.chain_id, json);
}

